import { MeshStandardNodeMaterial, Group, Mesh, PlaneGeometry, DirectionalLight, AmbientLight } from 'three/webgpu';
import { vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  // 1. STAGE & BACKDROP GP
  // Spec Colors
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const inkColor = new THREE.Color(colors.ink);
  const paperColor = new THREE.Color(colors.paper);
  const accentColor = new THREE.Color(colors.accent);
  const surfaceColor = new THREE.Color(colors.surface);

  // Vertical gradient backdrop (7x6 units at z=-2.5) to avoid flat void
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial({
    roughness: 0.9,
    metalness: 0.1,
    depthWrite: false
  });

  // Custom TSL gradient for backdrop
  const gradUV = uv();
  backdropMat.colorNode = mix(
    vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b),
    vec3(inkColor.r, inkColor.g, inkColor.b),
    gradUV.y
  );

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // Local Studio Lighting (to avoid uniform dead lighting on machined-metal elements)
  const localAmbient = new AmbientLight(colors.surface, 0.4);
  group.add(localAmbient);

  const localKeyLight = new DirectionalLight(colors.paper, 1.2);
  localKeyLight.position.set(2, 3, 2.5); // 30-45 degree key
  group.add(localKeyLight);

  const localRimLight = new DirectionalLight(colors.accent, 0.8);
  localRimLight.position.set(-2, -2, -1); // Opposite rim carrying accent hue
  group.add(localRimLight);

  // 2. HERO SUBJECT: MACHINED-METAL QUOTE PANEL
  // Interactive cards: PBR machined surface (roughness >= 0.5, metalness <= 0.55, clearcoat <= 0.25)
  const cardWidth = 3.2;
  const cardHeight = 2.0;
  const cardGeometry = new PlaneGeometry(cardWidth, cardHeight);

  const cardMaterial = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2
  });

  const cardMesh = new Mesh(cardGeometry, cardMaterial);
  cardMesh.castShadow = true;
  cardMesh.receiveShadow = true;
  group.add(cardMesh);

  // Load visualSpec image onto card if present
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      cardMaterial.map = texture;
      cardMaterial.needsUpdate = true;
    }).catch((err) => {
      console.warn("Failed loading texture asset", err);
    });
  } else {
    // Elegant fall-back brushed-metal look if image is missing
    cardMaterial.colorNode = mix(
      vec3(inkColor.r, inkColor.g, inkColor.b),
      vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b),
      uv().x
    );
  }

  // Shadow plane immediately below card to ground it
  const shadowGeo = new PlaneGeometry(cardWidth * 1.2, 0.2);
  const shadowMat = new MeshStandardNodeMaterial({
    color: colors.ink,
    transparent: true,
    opacity: 0.5,
    roughness: 1.0,
    metalness: 0.0
  });
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -(cardHeight / 2) - 0.1, 0.05);
  shadowMesh.rotation.x = -Math.PI * 0.4;
  group.add(shadowMesh);

  // 3. TEXT RENDERING
  // Nova Atelier display = Lora, text = JetBrains Mono
  const quoteText = ctx.fontAtlas.createText(
    "“The watch is an expression of time. Our work is to give that structure a soul.”", 
    {
      fontSize: 0.14,
      color: colors.paper,
      align: 'center',
      maxWidthPx: 800,
      letterSpacingPx: 1
    }
  );
  quoteText.position.set(0, 0.2, 0.1);
  group.add(quoteText);

  const authorText = ctx.fontAtlas.createText(
    "— ATELIER MASTER", 
    {
      fontSize: 0.09,
      color: colors.accent,
      align: 'center',
      maxWidthPx: 800,
      letterSpacingPx: 4
    }
  );
  authorText.position.set(0, -0.4, 0.1);
  group.add(authorText);

  // 4. BEHAVIORS & INTERACTION HANDLERS
  const timelines = [];

  const onHoverStart = () => {
    // rise-in behavior: lift 0.15 scene units, subtle tilt
    const tl = gsap.timeline();
    tl.to(cardMesh.position, {
      y: 0.15,
      z: 0.2,
      duration: 0.4,
      ease: 'power3.out'
    });
    tl.to(shadowMesh.scale, {
      x: 1.1,
      y: 1.1,
      duration: 0.4,
      ease: 'power3.out'
    }, 0);
    tl.to(shadowMesh.position, {
      y: -(cardHeight / 2) - 0.2,
      duration: 0.4,
      ease: 'power3.out'
    }, 0);
    timelines.push(tl);
  };

  const onHoverEnd = () => {
    // Weighted settle back to ground state
    const tl = gsap.timeline();
    tl.to(cardMesh.position, {
      y: 0.0,
      z: 0.0,
      duration: 0.6,
      ease: 'power4.out',
      runBackwards: false
    });
    tl.to(shadowMesh.scale, {
      x: 1.0,
      y: 1.0,
      duration: 0.6,
      ease: 'power4.out'
    }, 0);
    tl.to(shadowMesh.position, {
      y: -(cardHeight / 2) - 0.1,
      duration: 0.6,
      ease: 'power4.out'
    }, 0);
    timelines.push(tl);
  };

  const onClick = () => {
    // press-down on click (scale to 0.97 scene units)
    const tl = gsap.timeline();
    tl.to(cardMesh.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(2)'
    });
    tl.to(cardMesh.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.35,
      ease: 'power2.out'
    });
    timelines.push(tl);

    // Emit event mapping
    ctx.emit('hub-pricing.select', { id: 'pricing-quote' });
  };

  // Attach handlers via userData
  group.userData.handlers = {
    pointerover: onHoverStart,
    pointerout: onHoverEnd,
    pointerdown: onClick
  };

  // 5. CINEMATIC PRIMITIVES
  // Applies parallax-scroll (intensity: 0.25)
  const primitiveRefs = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives[prim.name]) {
        const ref = ctx.primitives[prim.name](group, prim.params);
        if (ref) {
          primitiveRefs.push(ref);
        }
      }
    });
  }

  // Fallback programmatic active primitive logic if matching list empty
  if (primitiveRefs.length === 0 && ctx.primitives['parallax-scroll']) {
    const ref = ctx.primitives['parallax-scroll'](group, { intensity: 0.25 });
    if (ref) primitiveRefs.push(ref);
  }

  // 6. CLEANUP HOOK
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    primitiveRefs.forEach((ref) => {
      if (typeof ref.cleanup === 'function') ref.cleanup();
    });
    cardGeometry.dispose();
    cardMaterial.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    backdropGeo.dispose();
    backdropMat.dispose();
  };

  return group;
}
